/// <summary>
/// Document handler for the Item Image Collector.
/// </summary>
[TFMMenu('RegisterItemImage', "@TFM:RegisterItemImage", "@TFM:RegisterItemImage", resourceStr(TFMItemImageCapture), true, true, ['Miscellaneous', 'MainMenu']),
    TFMDocumentType(classStr(TFMGetRegistrationConfiguration), 'RegisterItemImage', methodStr(TFMDocGetItemImages, GetItemRegistrationCollectors)),
    TFMDocumentType(classStr(TFMPostAdhocRegistration), 'RegisterItemImage', methodStr(TFMDocGetItemImages,postItemImage))]
class TFMDocGetItemImages extends TFMDocumentHandler
{
    boolean                 dimLocked;
    InventTable             inventTable;
    InventDim               inventDim;
    Common                  common;


}

Method.Source:
public TFMDocumentHandlerDescription description()
{
    TFMDocumentHandlerDescription ret;

    ret = "@TFM:RegisterItemImage";

    return ret;
}

public Map addTranslations()
{
    Map ret = new Map(Types::String, Types::String);

    ret.insert('RegisterItemImage', "@TFM:RegisterItemImage");

    return ret;
}

/// <summary>
/// Method to create the filter/header for the Register Image page.
/// </summary>
/// <returns>The Filter as an XML formatted string.</returns>
[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration RegisterItemImageHeader()
{
    TFMReferenceDataConfiguration linesHeader = new TFMReferenceDataConfiguration();
    linesHeader.addCollector(TFMGetReferenceData::defaultItemIdCollector(1));
    return linesHeader;
}

/// <summary>
/// Method to create a "Item Image Collector" configuration.
/// </summary>
/// <returns>A string</returns>
[TFMDocumentType(classStr(TFMGetRegistrationConfiguration), 'RegisterItemImage')]
protected str RegisterItemImageCollectors()
{

    this.addFunctionCollectors(methodStr(TFMDocGetItemImages,GetItemRegistrationCollectors));

    return "@TFM:MEL9";
}

/// <summary>
/// Method that returns the registration collectors for the create Quarantine order flow
/// </summary>
/// <returns>The registration collectors for the create Quarantine order flow</returns>
public Map GetItemRegistrationCollectors()
{
    Map returnMap = new Map(Types::string, Types::Class);
    int add = 10;
    InventDimParm           parm;
    parm.setActiveProductDim(EcoResProductDimGroupSetup::newInventTable(request.parmInventTable()));
    if (!dimLocked)
    {            
        returnMap = TFMInventDimHelper::GetInventDimCollectors(add, TFMInventDimSetup::Construct(request.parmInventTable()),parm);
    }
    add += returnMap.elements()*10 + 15;
    returnMap.insert(extendedTypeStr(ImageDataString),TFMRegistrationCollectorImageCapture::ImageCaptureStepMap(add,extendedTypeStr(ImageDataString),"@SYS59132","@SYS59132",''));
    return returnMap;
}

/// <summary>
/// Method to post Item Image registrations.
/// </summary>    
/// <returns>Message whether the operation ended in success or error.</returns>
[TFMPostMethod(tableStr(Common))]
protected str postItemImage()
{
    ItemId                              itemid;
    InventDimCombination                iDimCom;
    TFMRequestItemAndDimensionElement   postRequest = request;        
    str                                 mediaIDs = postRequest.getFieldValue(extendedTypeStr(ImageDataString));

    itemid = postRequest.parmItemId();//TFMHelper::ExtractItemId(inventDim, requestData, #ItemNumber);
    inventDim = InventDim::findOrCreate(postRequest.parmInventDim());//TFMHelper::ExtractInventDim(inventDim, itemid, requestData);


    iDimCom = InventDimCombination::find(itemid,inventDim.inventDimId);

    if (mediaIDs)
    {
        common = iDimCom;
        if (common == null)
        {
            common = InventTable::find(itemid);
        }
        TFMMediaQueue::AddMap2Queue(common, TFMMediaQueue::separateIDsAndComments(mediaIDs), postRequest.parmdeviceID());
    }

    return 'ok';
}
